style:
.btn {
    background-color: aquamarine;
    padding: 10px 20px;
    text-decoration: none;
    color: darkslategrey;
    font-weight: 600;
    border-radius: 6px;
}

#wrp-dash-root *{box-sizing:border-box;font-family:var(--font-stack,'Inter',sans-serif)}
#wrp-dash-root{--g:#22c55e;--r:#ef4444;--o:#f59e0b;--b:#3b82f6;--p:#7c3aed;--grey:#6b7280;padding:0 2px 24px}
.wrp-loading{padding:40px;text-align:center;color:var(--text-muted)}
.wrp-section-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);margin:20px 0 8px}
.wrp-row{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:4px}
/* -- scope bar -- */
.wrp-scope{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:16px;padding:10px 14px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px}
.wrp-scope label{font-size:12px;color:var(--text-muted);margin-bottom:0;margin-right:2px}
.wrp-scope select{font-size:12px;padding:3px 6px;border:1px solid var(--border-color);border-radius:4px;background:var(--bg-color,#fff);color:var(--text-color,#111);cursor:pointer}
.wrp-scope button{font-size:12px;padding:4px 12px;border:none;border-radius:4px;background:var(--primary,#4f46e5);color:#fff;cursor:pointer}
/* -- cards -- */
.wrp-card{flex:1;min-width:90px;padding:12px 14px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px}
.wrp-card.clickable{cursor:pointer;transition:box-shadow .15s,transform .1s}
.wrp-card.clickable:hover{box-shadow:0 4px 12px rgba(0,0,0,.12);transform:translateY(-1px)}
.wrp-card-val{font-size:22px;font-weight:700;line-height:1.1}
.wrp-card-lbl{font-size:11px;color:var(--text-muted);margin-top:2px}
.wrp-card-sub{font-size:10px;color:var(--text-muted)}
/* -- pipeline bars -- */
.wrp-pipe-row{display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--border-color,#f3f4f6)}
.wrp-pipe-row:last-child{border:none}
.wrp-pipe-lbl{min-width:120px;font-size:12px;color:var(--text-color)}
.wrp-pipe-bar{flex:1;height:10px;background:var(--border-color,#e5e7eb);border-radius:5px;overflow:hidden}
.wrp-pipe-fill{height:100%;border-radius:5px;transition:width .6s ease}
.wrp-pipe-cnt{min-width:50px;text-align:right;font-size:12px;font-weight:600}
.wrp-pipe-pct{min-width:38px;text-align:right;font-size:11px;color:var(--text-muted)}
.wrp-pipe-row.clickable{cursor:pointer;border-radius:4px;padding:5px 4px;margin:0 -4px}
.wrp-pipe-row.clickable:hover{background:var(--bg-color,#f9fafb)}
/* -- alert cards -- */
.wrp-alert{flex:1;min-width:150px;padding:12px 14px;border-radius:8px;border:1px solid;cursor:pointer;transition:box-shadow .15s,transform .1s}
.wrp-alert:hover{box-shadow:0 4px 12px rgba(0,0,0,.12);transform:translateY(-1px)}
.wrp-alert-val{font-size:20px;font-weight:700}
.wrp-alert-lbl{font-size:11px;margin-top:2px}
.red{background:#fef2f2;border-color:#fecaca;color:#991b1b}.red .wrp-alert-val{color:#dc2626}
.orange{background:#fffbeb;border-color:#fde68a;color:#92400e}.orange .wrp-alert-val{color:#d97706}
.blue{background:#eff6ff;border-color:#bfdbfe;color:#1e40af}.blue .wrp-alert-val{color:#2563eb}
/* -- drill panel -- */
.wrp-panel-overlay{position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:1040;display:none}
.wrp-panel-overlay.open{display:block}
.wrp-panel{position:fixed;top:0;right:0;bottom:0;width:min(640px,100vw);background:var(--card-bg,#fff);box-shadow:-4px 0 24px rgba(0,0,0,.18);z-index:1041;display:flex;flex-direction:column;transform:translateX(100%);transition:transform .25s ease}
.wrp-panel.open{transform:translateX(0)}
.wrp-panel-head{display:flex;align-items:center;gap:8px;padding:14px 18px;border-bottom:1px solid var(--border-color);flex-shrink:0}
.wrp-panel-head button.back{background:none;border:1px solid var(--border-color);border-radius:4px;padding:3px 10px;cursor:pointer;font-size:12px}
.wrp-panel-head .title{flex:1;font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wrp-panel-head button.close{background:none;border:none;font-size:18px;cursor:pointer;color:var(--text-muted);line-height:1}
.wrp-panel-body{flex:1;overflow-y:auto;padding:14px 18px}
.wrp-breadcrumb{font-size:11px;color:var(--text-muted);margin-bottom:12px}
.wrp-breadcrumb span{cursor:pointer;color:var(--primary,#4f46e5)}
.wrp-breadcrumb span:hover{text-decoration:underline}
.wrp-table-wrap{overflow-x:auto}
table.wrp-table{width:100%;border-collapse:collapse;font-size:12px}
table.wrp-table th{background:var(--bg-color,#f9fafb);padding:7px 10px;text-align:left;font-weight:600;border-bottom:2px solid var(--border-color);white-space:nowrap}
table.wrp-table td{padding:7px 10px;border-bottom:1px solid var(--border-color,#f3f4f6);vertical-align:top}
table.wrp-table tr.drillable{cursor:pointer}
table.wrp-table tr.drillable:hover td{background:var(--bg-color,#f0f9ff)}
.wrp-badge{display:inline-block;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:600}
.wrp-empty{text-align:center;padding:40px;color:var(--text-muted);font-size:13px}
.wrp-panel-loading{text-align:center;padding:60px;color:var(--text-muted)}

script:
(function () {
  const ROOT  = document.getElementById('wrp-dash-root');
  const PANEL_TITLES = {
    unvisited:            'Unvisited Households',
    visited_no_change_7d: 'Visited — No Change in 7 Days',
    stagnant_14d:         'Stagnant 14+ Days (2+ Visits)',
    aadhaar_internal_sla: 'Aadhaar Internal Applied — SLA Exceeded',
    aadhaar_external_sla: 'Aadhaar External Applied — SLA Exceeded',
    income_sla:           'Income Cert Applied — SLA Exceeded',
    cmchis_sla:           'CMCHIS Applied — SLA Exceeded',
    co_below_25:          'COs Below 25% Visit Target',
    co_below_50:          'COs 25–50% Visit Target',
    co_below_75:          'COs 50–75% Visit Target',
    co_low_impact:        'Low-Impact COs',
  };
  const LEVEL_LABELS = ['org','iu','street','co','hh','individual'];
  const LEVEL_NAMES  = {org:'Organisation',iu:'Intervention Unit',street:'Street',co:'CO',hh:'Household',individual:'Individual'};

  let _data       = null;
  let _filters    = {};
  let _navStack   = [];  // [{metric, level, parent, title, rows, columns}]
  let _overlayEl  = null;
  let _panelEl    = null;

  // ── API ────────────────────────────────────────────────────────────────
  function api(method, args) {
    return new Promise((res, rej) => {
      frappe.call({ method, args,
        callback: r => res(r.message),
        error:    e => rej(e),
      });
    });
  }

  // ── Init ───────────────────────────────────────────────────────────────
  async function init() {
    ROOT.innerHTML = '<div class="wrp-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div>';
    _data = await api('changemakers.dashboard_api.get_dashboard_overview', { filters: _filters });
    if (_data && _data.error === 'no_access') {
      ROOT.innerHTML = '<div class="wrp-loading">No data access for your organisation.</div>';
      return;
    }
    renderDashboard();
    buildPanel();
  }

  // ── Render main dashboard ──────────────────────────────────────────────
  function renderDashboard() {
    const d = _data;
    const s = d.structure;
    const p = d.pipeline;
    const a = d.alerts;
    const c = d.co_performance;

    // ── Scope bar ──
    let scopeHtml = `<div class="wrp-scope">
      <label>Scope:</label>
      <label>Org</label><select id="wrp-f-org"><option value="">All</option></select>
      <label>IU</label><select id="wrp-f-iu"><option value="">All</option></select>
      <label>Street</label><select id="wrp-f-st"><option value="">All</option></select>
      <button onclick="wrpDashRefresh()">Apply</button>
    </div>`;
    populateScopeOptions();

    // ── Structure row ──
    let structHtml = `<div class="wrp-section-title">Programme Structure</div>
    <div class="wrp-row">
      ${smallCard(s.orgs,    'Organisations',       null, '#4f46e5')}
      ${smallCard(s.ius,     'Intervention Units',  null, '#4f46e5')}
      ${smallCard(s.streets, 'Streets',             null, '#4f46e5')}
      ${smallCard(s.cos,     'Community Organisers',null, '#4f46e5')}
      ${smallCard(s.acs,     'Area Coordinators',   null, '#4f46e5')}
      ${smallCard(s.pms,     'Programme Managers',  null, '#4f46e5')}
    </div>`;

    // ── Pipeline ──
    const total = p.total || 1;
    const pRows = [
      {key:'unvisited',       label:'Unvisited',          color:'#6b7280'},
      {key:'missing_both',    label:'Missing Both Docs',  color:'#f59e0b'},
      {key:'missing_aadhaar', label:'Missing Aadhaar',    color:'#f59e0b'},
      {key:'missing_income',  label:'Missing Income Cert',color:'#f59e0b'},
      {key:'docs_ready',      label:'Docs Ready',         color:'#8b5cf6'},
      {key:'applied',         label:'CMCHIS Applied',     color:'#3b82f6'},
      {key:'active',          label:'CMCHIS Active ★', color:'#22c55e'},
      {key:'rejected',        label:'Rejected',           color:'#ef4444'},
    ];
    let pipeHtml = `<div class="wrp-section-title">Pipeline — ${fmt(p.total)} Households</div>
    <div style="padding:8px 12px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px">`;
    for (const r of pRows) {
      const cnt = p[r.key] || 0;
      const pct = total ? (cnt / total * 100).toFixed(1) : 0;
      const drill = r.key === 'unvisited' ? 'unvisited' : null;
      const cls   = drill ? 'clickable' : '';
      const click = drill ? `onclick="wrpDrill('${drill}','org',null,'${PANEL_TITLES[drill]||r.label}')"` : '';
      pipeHtml += `<div class="wrp-pipe-row ${cls}" ${click}>
        <div class="wrp-pipe-lbl">${r.label}</div>
        <div class="wrp-pipe-bar"><div class="wrp-pipe-fill" style="width:${pct}%;background:${r.color}"></div></div>
        <div class="wrp-pipe-cnt" style="color:${r.color}">${fmt(cnt)}</div>
        <div class="wrp-pipe-pct">${pct}%</div>
      </div>`;
    }
    pipeHtml += '</div>';

    // ── Alerts ──
    const alertCards = [
      {key:'visited_no_change_7d', val:a.visited_no_change_7d, lbl:'Visited — No Change 7d',       cls:'orange'},
      {key:'stagnant_14d',         val:a.stagnant_14d,         lbl:'Stagnant 14d+ (2+ visits)',     cls:'orange'},
      {key:'aadhaar_internal_sla', val:a.aadhaar_internal_sla, lbl:'Aadhaar Internal Applied → SLA', cls:'red'},
      {key:'aadhaar_external_sla', val:a.aadhaar_external_sla, lbl:'Aadhaar External Applied → SLA', cls:'red'},
      {key:'income_sla',           val:a.income_sla,           lbl:'Income Cert Applied → SLA',      cls:'red'},
      {key:'cmchis_sla',           val:a.cmchis_sla,           lbl:'CMCHIS Applied → SLA',           cls:'blue'},
    ];
    let alertHtml = `<div class="wrp-section-title">Alerts ⚠️</div><div class="wrp-row">`;
    for (const c of alertCards) {
      alertHtml += `<div class="wrp-alert ${c.cls}" onclick="wrpDrill('${c.key}','org',null,'${PANEL_TITLES[c.key]||c.lbl}')">
        <div class="wrp-alert-val">${fmt(c.val)}</div>
        <div class="wrp-alert-lbl">${c.lbl}</div>
      </div>`;
    }
    alertHtml += '</div>';

    // ── CO performance ──
    const cc = c.counts;
    const coCards = [
      {key:'co_below_25',  val:cc.below_25,   lbl:'COs &lt;25% target',   cls:'red'},
      {key:'co_below_50',  val:cc.below_50,   lbl:'COs 25–50% target',    cls:'orange'},
      {key:'co_below_75',  val:cc.below_75,   lbl:'COs 50–75% target',    cls:'orange'},
      {key:'co_low_impact',val:cc.low_impact, lbl:'Low-Impact COs',       cls:'blue'},
    ];
    let coHtml = `<div class="wrp-section-title">CO Performance</div><div class="wrp-row">`;
    for (const c of coCards) {
      coHtml += `<div class="wrp-alert ${c.cls}" onclick="wrpDrill('${c.key}','co',null,'${PANEL_TITLES[c.key]||c.lbl}')">
        <div class="wrp-alert-val">${fmt(c.val)}</div>
        <div class="wrp-alert-lbl">${c.lbl}</div>
      </div>`;
    }
    coHtml += '</div>';

    ROOT.innerHTML = scopeHtml + structHtml + pipeHtml + alertHtml + coHtml;
    populateScopeOptions();
  }

  // ── Scope selects ──────────────────────────────────────────────────────
  async function populateScopeOptions() {
    const [orgs, ius, streets] = await Promise.all([
      frappe.db.get_list('Street List  - WRP', {fields:['implementing_org'], group_by:'implementing_org', limit:200}),
      frappe.db.get_list('Street List  - WRP', {fields:['intervention_units'], group_by:'intervention_units', limit:500}),
      frappe.db.get_list('Street List  - WRP', {fields:['name'], limit:1000}),
    ]).catch(() => [[], [], []]);
    const fill = (id, items, field) => {
      const el = document.getElementById(id);
      if (!el) return;
      const cur = el.value;
      el.innerHTML = '<option value="">All</option>' +
        items.filter(r => r[field]).map(r => `<option${r[field]===cur?' selected':''}>${esc(r[field])}</option>`).join('');
    };
    fill('wrp-f-org', orgs,    'implementing_org');
    fill('wrp-f-iu',  ius,     'intervention_units');
    fill('wrp-f-st',  streets, 'name');
  }

  window.wrpDashRefresh = function () {
    _filters = {
      implementing_org:  document.getElementById('wrp-f-org')?.value || '',
      intervention_unit: document.getElementById('wrp-f-iu')?.value  || '',
      street:            document.getElementById('wrp-f-st')?.value  || '',
    };
    Object.keys(_filters).forEach(k => { if (!_filters[k]) delete _filters[k]; });
    init();
  };

  // ── Panel ──────────────────────────────────────────────────────────────
  function buildPanel() {
    if (document.getElementById('wrp-panel-overlay')) return;
    _overlayEl = document.createElement('div');
    _overlayEl.id = 'wrp-panel-overlay';
    _overlayEl.className = 'wrp-panel-overlay';
    _overlayEl.onclick = e => { if (e.target === _overlayEl) closePanel(); };

    _panelEl = document.createElement('div');
    _panelEl.className = 'wrp-panel';
    _panelEl.innerHTML = `
      <div class="wrp-panel-head">
        <button class="back" onclick="wrpPanelBack()">&#8592; Back</button>
        <div class="title" id="wrp-panel-title">Loading…</div>
        <button class="close" onclick="wrpPanelClose()">&times;</button>
      </div>
      <div class="wrp-panel-body" id="wrp-panel-body">
        <div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div>
      </div>`;
    _overlayEl.appendChild(_panelEl);
    document.body.appendChild(_overlayEl);
  }

  function openPanel() {
    _overlayEl.classList.add('open');
    setTimeout(() => _panelEl.classList.add('open'), 10);
  }

  function closePanel() {
    _panelEl.classList.remove('open');
    _overlayEl.classList.remove('open');
    _navStack = [];
  }

  window.wrpPanelClose = closePanel;

  window.wrpPanelBack = function () {
    if (_navStack.length <= 1) { closePanel(); return; }
    _navStack.pop();
    const prev = _navStack[_navStack.length - 1];
    renderPanelData(prev);
  };

  window.wrpDrill = async function (metric, level, parent, titleHint) {
    openPanel();
    document.getElementById('wrp-panel-title').textContent = titleHint || PANEL_TITLES[metric] || metric;
    document.getElementById('wrp-panel-body').innerHTML =
      '<div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div>';

    const result = await api('changemakers.dashboard_api.get_drilldown', {
      metric, level, parent: parent || null,
      filters: _filters,
    });

    const frame = { metric, level, parent, title: titleHint || PANEL_TITLES[metric] || metric,
                    rows: result.rows || [], columns: result.columns || [] };
    _navStack.push(frame);
    renderPanelData(frame);
  };

  function renderPanelData(frame) {
    document.getElementById('wrp-panel-title').textContent = frame.title;
    const body = document.getElementById('wrp-panel-body');

    // Breadcrumb
    let crumb = '<div class="wrp-breadcrumb">';
    for (let i = 0; i < _navStack.length; i++) {
      const n = _navStack[i];
      if (i < _navStack.length - 1) {
        crumb += `<span onclick="wrpPanelJump(${i})">${esc(n.title)}</span> &rsaquo; `;
      } else {
        crumb += `<b>${esc(n.title)}</b>`;
      }
    }
    crumb += '</div>';

    const { rows, columns } = frame;
    if (!rows || rows.length === 0) {
      body.innerHTML = crumb + '<div class="wrp-empty">✓ No issues found at this level.</div>';
      return;
    }

    // Check if this is an aggregated (org/iu/street) level — has a 'count' field
    const isAgg = columns.length === 2 && columns[1].fieldname === 'count';
    const nextLevel = LEVEL_LABELS[LEVEL_LABELS.indexOf(frame.level) + 1] || null;

    let html = crumb + '<div class="wrp-table-wrap"><table class="wrp-table"><thead><tr>';
    for (const col of columns) {
      html += `<th>${esc(col.label)}</th>`;
    }
    if (isAgg) html += '<th></th>';
    html += '</tr></thead><tbody>';

    for (const row of rows) {
      const drillable = isAgg && nextLevel;
      html += `<tr class="${drillable ? 'drillable' : ''}"${drillable ?
        ` onclick="wrpDrillDown('${frame.metric}','${nextLevel}','${esc(row.name)}','${esc(frame.title)} › ${esc(row.name)}')"` : ''}>`;
      for (const col of columns) {
        let val = row[col.fieldname];
        if (val === null || val === undefined) val = '';
        html += `<td>${esc(String(val))}</td>`;
      }
      if (isAgg) html += `<td style="color:var(--primary,#4f46e5);font-size:11px">Drill →</td>`;
      html += '</tr>';
    }
    html += '</tbody></table></div>';
    html += `<div style="font-size:11px;color:var(--text-muted);margin-top:10px;text-align:right">${fmt(rows.length)} row${rows.length!==1?'s':''}</div>`;
    body.innerHTML = html;
  }

  window.wrpPanelJump = function (idx) {
    _navStack = _navStack.slice(0, idx + 1);
    renderPanelData(_navStack[_navStack.length - 1]);
  };

  window.wrpDrillDown = async function (metric, level, parent, title) {
    document.getElementById('wrp-panel-body').innerHTML =
      '<div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading…</div>';
    const result = await api('changemakers.dashboard_api.get_drilldown', {
      metric, level, parent, filters: _filters,
    });
    const frame = { metric, level, parent, title,
                    rows: result.rows || [], columns: result.columns || [] };
    _navStack.push(frame);
    renderPanelData(frame);
  };

  // ── Helpers ────────────────────────────────────────────────────────────
  function smallCard(val, lbl, sub, color) {
    return `<div class="wrp-card">
      <div class="wrp-card-val" style="color:${color}">${fmt(val)}</div>
      <div class="wrp-card-lbl">${lbl}</div>
      ${sub ? `<div class="wrp-card-sub">${sub}</div>` : ''}
    </div>`;
  }
  function fmt(n) {
    if (n === null || n === undefined) return '—';
    return Number(n).toLocaleString();
  }
  function esc(s) {
    if (!s) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // ── Register whitelist ─────────────────────────────────────────────────
  frappe.whitelist_hook = frappe.whitelist_hook || {};

  // ── Boot ──────────────────────────────────────────────────────────────
  frappe.ready ? frappe.ready(init) : init();
})();
